import sys; sys.path[:0]=['/workspace/project','/opt/emicro-deps']
import syntax
from compiler import compiler as C
text='match() drop;(not(match(A,C,A)) or match(A,B,A)) allow;(contains() and (match(C) or endswith(C))) allow;match(B) drop;'
rules,_,_=syntax.parse(text)
index={'A':0,'B':1,'C':2}
# rebuild combine but keep the unminimized result
def build(rules,width,index):
    atoms={}
    def language(predicate):
        kind=predicate[0]
        if kind in ('match','startswith','endswith','contains'):
            key=(kind,tuple(index[n] for n in predicate[1]))
            m=atoms.get(key)
            if m is None:
                m=C.atom_language(key[0],key[1],width); atoms[key]=m
            return m
        if kind=='not': return ~language(predicate[1])
        l=language(predicate[1]); r=language(predicate[2])
        return (l|r) if kind=='or' else (l&r)
    allow=None; deny=None
    for pred,act in rules:
        m=language(pred)
        if act: allow = m if allow is None else (allow|m)
        else: deny = m if deny is None else (deny|m)
    return allow, deny
allow,deny=build(rules,3,index)
print('allow states',allow.States, allow.Initial, allow.Final, len(allow.delta))
print('deny states',deny.States, deny.Initial, deny.Final, len(deny.delta))
def t(d,word):
    s=d.Initial
    for x in word:
        try: s=d.delta[s][x]
        except KeyError: return False
    return s in d.Final
res = allow & ~deny
print('res', res.States, res.Initial, res.Final)
for w in [(0,),(1,),(2,),(),(0,2,0),(2,),(0,2),(1,0)]:
    print(w,'res',t(res,list(w)),'allow',t(allow,list(w)),'deny',t(deny,list(w)))
m=res.minimal()
print('minimal', m.States, m.Initial, m.Final)
for w in [(0,),(1,),(2,),(),(0,2,0),(2,),(0,2),(1,0)]:
    print(w,'min',t(m,list(w)))
